ALTER TABLE blank_stock ADD reserved INT NOT NULL DEFAULT 0;
CREATE TABLE pending_orders (id VARCHAR(36) PRIMARY KEY, session_key VARCHAR(64), request_id VARCHAR(36), request_fingerprint VARCHAR(64), status VARCHAR(255), created_at TIMESTAMP(6), expires_at TIMESTAMP(6), subtotal INT NOT NULL, shipping INT NOT NULL, total INT NOT NULL, name VARCHAR(255), email VARCHAR(255), phone VARCHAR(255), line1 VARCHAR(255), line2 VARCHAR(255), city VARCHAR(255), state VARCHAR(255), pin_code VARCHAR(255), UNIQUE(session_key,request_id));
CREATE INDEX pending_order_expiry ON pending_orders(status,expires_at);
CREATE TABLE pending_order_lines (order_id VARCHAR(36) NOT NULL, position INT NOT NULL, stock_id BIGINT, slug VARCHAR(255), name VARCHAR(255), colour VARCHAR(255), size VARCHAR(255), quantity INT NOT NULL, unit_price INT NOT NULL, image VARCHAR(255), PRIMARY KEY(order_id,position), FOREIGN KEY(order_id) REFERENCES pending_orders(id), FOREIGN KEY(stock_id) REFERENCES blank_stock(id));
